// v119.7: 🔎 ACHAR NA LOJA — produto parado que ia virar rebaixa: a repositora precisa achar antes
var alC=null,alEd={};
function alCarregar(){v9Api({acao:'acharLista'},function(r){alC=r;if($('tVAL').classList.contains('on')&&valAba==='AL')renderVAL();},function(){if(!alC){alC={itens:[]};renderVAL();}});}
function alResp(it,x,b){if(b)b.disabled=true;x.acao='acharResp';x.id=it.id;v9Api(x,function(r){toast(x.achou==='S'?'✅ Salvo! Obrigado':'Registrado — o Celio vai ver','ok');delete alEd[it.id];alCarregar();},function(){if(b)b.disabled=false;});}
function alRender(box){
  $('valTit').textContent='🔎 Achar na loja';$('valProg').textContent='';
  $('valDica').innerHTML='Produtos <b>parados no sistema</b>. Vá até o local e diga se o produto <b>está na loja</b>.';
  if(!alC){box.innerHTML='<p class="dica">Carregando…</p>';alCarregar();return;}
  var its=alC.itens||[],np=its.filter(function(i){return i.status==='PENDENTE';}).length;
  $('valTabAL').textContent='🔎 Achar'+(np?' ('+np+')':'');
  if(!its.length){box.innerHTML='<p class="dica" style="font-size:16px;margin-top:16px">Nenhum produto para achar. 👍</p>';return;}
  its.forEach(function(it){
    var d=document.createElement('div'),e=alEd[it.id];d.className='v9Box vf'+(it.status==='PENDENTE'?'':' feito');
    var h='<div class="v9D">'+esc(it.desc)+'</div><div class="v9M">'+(it.local?'📍 '+esc(it.local)+' · ':'')+'SKU '+esc(it.sku)+(alC.tudo&&it.quem?' · 👩 '+esc(it.quem):'')+'</div>';
    if(it.status!=='PENDENTE')h+='<div class="vfR '+(it.status==='ACHOU'?'ok':'er')+'">'+(it.status==='ACHOU'?'✅ Achado — '+esc(it.total)+' un · val. '+esc(vfCurta(it.validade)):'🚫 Não achado — o Celio vai ver')+'</div>';
    else if(!e)h+='<div class="alAv">⏳ Sem venda'+(it.dias?' há '+esc(it.dias)+' dias':'')+' — precisamos saber se ele está na loja</div><div class="vfQ">Você achou este produto?</div><div class="alBt"><button type="button" class="s">✅ ACHEI</button><button type="button" class="n">🚫 NÃO ACHEI</button></div>';
    else h+='<div class="vfQ">Qual a <b>validade</b> do produto?</div><div class="vfOps"></div><div class="alVp"></div><div class="v9Lbl">QUANTAS TEM?</div><div class="alIn"><div><div class="v9M">Na gôndola</div><input type="text" inputmode="decimal" class="alG" placeholder="0" value="'+esc(e.g||'')+'"></div><div><div class="v9M">No depósito</div><input type="text" inputmode="decimal" class="alD" placeholder="0" value="'+esc(e.d||'')+'"></div></div><div class="alTot"></div><button class="btn ok alOk" style="margin-top:12px">SALVAR</button><button class="btn cancel alVolta">VOLTAR</button>';
    d.innerHTML=h;
    var bs=d.querySelector('.alBt');if(bs){bs.querySelector('.s').onclick=function(){vibra();alEd[it.id]={v:'',g:'',d:''};renderVAL();};bs.querySelector('.n').onclick=function(){if(!confirm('Não achou mesmo? Procure também no depósito antes de confirmar.'))return;alResp(it,{achou:'N'},this);};}
    if(e){var ops=d.querySelector('.vfOps');
      (it.validades||[]).forEach(function(v){var b=document.createElement('button');b.type='button';b.textContent=vfCurta(v);if(!e.outra&&e.v===v)b.className='alSel';b.onclick=function(){vibra();e.v=v;e.outra=false;renderVAL();};ops.appendChild(b);});
      var bo=document.createElement('button');bo.type='button';bo.className='out'+(e.outra?' alSel':'');bo.textContent='📅 OUTRA';bo.onclick=function(){vibra();e.outra=!e.outra;e.v='';renderVAL();};ops.appendChild(bo);
      if(e.outra)vpMontar(d.querySelector('.alVp'),e.v,function(v){e.v=v;},{modos:['ROL']});
      var tot=function(){var a=Number(String(e.g||'0').replace(',','.'))||0,b=Number(String(e.d||'0').replace(',','.'))||0;d.querySelector('.alTot').innerHTML='Total achado: <b>'+(Math.round((a+b)*1000)/1000)+' un</b>';};
      d.querySelector('.alG').oninput=function(){e.g=this.value;tot();};d.querySelector('.alD').oninput=function(){e.d=this.value;tot();};tot();
      d.querySelector('.alVolta').onclick=function(){delete alEd[it.id];renderVAL();};
      d.querySelector('.alOk').onclick=function(){if(!e.v)return toast('Escolha a validade','err');if(String(e.g).trim()===''&&String(e.d).trim()==='')return toast('Quantas tem? (gôndola e depósito)','err');alResp(it,{achou:'S',validade:e.v,gondola:String(e.g||'0'),deposito:String(e.d||'0')},this);};
    }
    $('valLista').appendChild(d);
  });
}
